    &lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;${hazards.map(h =&gt; html`&lt;th scope="col"&gt;${h}&lt;/th&gt;`)}&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;&lt;/tbody&gt;
  &lt;/table&gt;`;
  const tbody = table.querySelector("tbody");
  for (const c of components) {
    const tr = html`&lt;tr&gt;&lt;th scope="row"&gt;${c}&lt;/th&gt;&lt;/tr&gt;`;
    for (const h of hazards) {
      const v = counts.get(c + "|" + h) ?? 0;
      const selected = component === c && hazard === h;
      const td = html`&lt;td tabindex="0" class=${selected ? "selected" : ""}
        style=${`background:${v ? color(Math.max(v, maxV * 0.12)) : "#f6f4ef"};color:${v &gt; maxV * 0.5 ? "#ffffff" : "#1f2a33"}`}
        title=${`${c}, ${h}: ${fmtN(Math.round(v))} ${measureLabel}`}&gt;${v ? fmtN(Math.round(v)) : ""}&lt;/td&gt;`;
      const pick = () =&gt; {
        setInput(viewof component, selected ? "All" : c);
        setInput(viewof hazard, selected ? "All" : h);
      };
      td.onclick = pick;
      td.onkeydown = e =&gt; { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(); } };
      tr.append(td);
    }
    tbody.append(tr);
  }
  const wrap = html`&lt;div class="heat-wrap"&gt;&lt;/div&gt;`;
  wrap.append(table);
  return wrap;
}

